package uk.ac.ravensbourne.casevault.security;
import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import uk.ac.ravensbourne.casevault.audit.PersistentAuditService; import uk.ac.ravensbourne.casevault.repository.UserAccountRepository;
/** Changes a password only after current-password verification and revokes all sessions (CWE-287/CWE-613). */
@Service public class PasswordChangeService { private final UserAccountRepository users; private final PasswordEncoder encoder; private final PasswordPolicy policy; private final SessionRevocationService revocations; private final PersistentAuditService audit; public PasswordChangeService(UserAccountRepository u,PasswordEncoder e,PasswordPolicy p,SessionRevocationService r,PersistentAuditService a){users=u;encoder=e;policy=p;revocations=r;audit=a;} @Transactional public void change(UserPrincipal p,String current,String next){var user=users.findById(p.id()).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!encoder.matches(current,user.getPasswordHash()))throw new IllegalArgumentException("Invalid credentials");policy.validate(next,user.getEmail());user.changePassword(encoder.encode(next));revocations.revokeAll(user.getEmail());audit.record(p,"PASSWORD_CHANGED","ACCOUNT",user.getId(),"changed");} }
